// Traduce la respuesta a algo legible en el historial de n8n.
//
// 409 wellness_disabled NO es un error: es el modulo apagado a proposito con
// NOTIFICATIONS_WELLNESS_ENABLED=false. Marcarlo como fallo llenaria el
// historial de rojo cuando todo esta correcto.
const status = $json.statusCode ?? 0;
const body = $json.body ?? {};

if (status === 409 && body.reason === 'wellness_disabled') {
  return [{ json: { resultado: 'inerte', mensaje: 'Modulo de bienestar apagado en el servidor.', alerta: false } }];
}

if (status !== 200 || body.ok !== true) {
  return [{ json: { resultado: 'fallo', status, mensaje: body.message || 'Laravel no acepto la tanda.', alerta: true } }];
}

return [{ json: {
  resultado: 'ok',
  considerados: body.considered ?? 0,
  enviados: body.sent ?? 0,
  no_enviados: body.suppressed ?? 0,
  alerta: false,
  nota: 'Los no enviados no son errores: son preferencias, horas de silencio o limites de frecuencia.'
} }];
